function tableExists(PDO $pdo,string $table):bool {try{$pdo->query('SELECT 1 FROM `'.$table.'` LIMIT 1');return true;}catch(Throwable){return false;}}
function cols(PDO $pdo,string $table):array {static $cache=[];if(isset($cache[$table]))return $cache[$table];$rows=$pdo->query('SHOW COLUMNS FROM `'.$table.'`')->fetchAll();return $cache[$table]=array_column($rows,'Field');}
function add(PDO $pdo,string $table,array $data):int {$allowed=array_flip(cols($pdo,$table));$data=array_intersect_key($data,$allowed);if(!$data)throw new RuntimeException('Nenhum campo compatível em '.$table);$fields=array_keys($data);$sql='INSERT INTO `'.$table.'` (`'.implode('`,`',$fields).'`) VALUES (:'.implode(',:',$fields).')';$pdo->prepare($sql)->execute($data);return(int)$pdo->lastInsertId();}
function role(PDO $pdo,string $slug):int {$q=$pdo->prepare('SELECT id FROM roles WHERE slug=:s LIMIT 1');$q->execute(['s'=>$slug]);$id=(int)$q->fetchColumn();if(!$id)throw new RuntimeException('Perfil obrigatório ausente: '.$slug);return$id;}
function randomPassword():string {return 'Demo!'.random_int(100000,999999).'Aa';}
