function demo(PDO $pdo):array|false {$q=$pdo->prepare('SELECT * FROM tenants WHERE slug=:s LIMIT 1');$q->execute(['s'=>AUTO_DEMO_SLUG]);return$q->fetch();}
function enableModules(PDO $pdo,int $tenant):void {if(!tableExists($pdo,'tenant_modules'))return;$slugs=['products','stock','finance','behavior','packages','loyalty','waitlist'];$marks=implode(',',array_fill(0,count($slugs),'?'));$q=$pdo->prepare("SELECT id FROM modules WHERE slug IN ($marks) AND active=1");$q->execute($slugs);$st=$pdo->prepare('INSERT INTO tenant_modules(tenant_id,module_id,enabled)VALUES(:t,:m,1) ON DUPLICATE KEY UPDATE enabled=1');foreach($q->fetchAll(PDO::FETCH_COLUMN) as $m)$st->execute(['t'=>$tenant,'m'=>$m]);}
function professional(PDO $pdo,int $tenant,int $unit,int $userId,string $name,string $email,string $specialty,float $commission):int {return add($pdo,'professionals',['tenant_id'=>$tenant,'unit_id'=>$unit,'user_id'=>$userId,'name'=>$name,'public_slug'=>strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$name)?:$name),'-')),'email'=>$email,'phone'=>'8199000'.random_int(1000,9999),'specialty'=>$specialty,'commission_percent'=>$commission,'active'=>1,'created_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);}

